/* MUTANT sleepTimer.invertOne — generated by make-mutants.mjs from src/renderer/src/lib/sleepTimer.ts */
export const MUTANT = "sleepTimer.invertOne"
/**
 * Sleep timer — pure logic (no DOM / no store imports) so it can be unit
 * tested in isolation. The player store owns the clock and the audio side
 * effects; everything decidable from plain numbers lives here.
 *
 *   minute  → pause once the countdown runs out (15/30/60 min)
 *   track   → pause when the current track ends (no auto-advance)
 *   queue   → pause when the last track of the queue ends (no wrap-around)
 *
 * The timer is intentionally *not* persisted: a fresh app start always
 * begins with the sleep timer off.
 */

export type SleepMode = 'minute' | 'track' | 'queue'

export interface SleepTimer {
  mode: SleepMode
  /** wall-clock ms when a countdown fires — null for ended-driven modes */
  deadline: number | null
  /** seconds chosen for 'minute' mode (15/30/60) */
  minutes: number | null
  /** the play mode active when the timer was armed (kept for UI info) */
  startMode: string
}

export const SLEEP_MINUTES = [15, 30, 60] as const

/** countdown arm: `minutes` from now */
export function armMinutes(minutes: number, now: number, playMode = 'list'): SleepTimer {
  const mins = Number.isFinite(minutes) && minutes > 0 ? Math.floor(minutes) : 0
  return {
    mode: 'minute',
    deadline: now + mins * 60_000,
    minutes: mins,
    startMode: playMode
  }
}

/** arm so the player pauses when the *current* track ends */
export function armTrackEnd(playMode = 'list'): SleepTimer {
  return { mode: 'track', deadline: null, minutes: null, startMode: playMode }
}

/** arm so the player pauses when the *last* track of the queue ends */
export function armQueueEnd(playMode = 'list'): SleepTimer {
  return { mode: 'queue', deadline: null, minutes: null, startMode: playMode }
}

/** ms until the countdown fires; null for non-countdown modes */
export function sleepRemainingMs(timer: SleepTimer | null | undefined, now: number): number | null {
  if (!timer || timer.mode !== 'minute' || timer.deadline === null) return null
  return Math.max(0, timer.deadline - now)
}

/** whole seconds left, rounded up (1:00 → 60, 59.4s → 60) */
export function sleepRemainingSeconds(
  timer: SleepTimer | null | undefined,
  now: number
): number | null {
  const ms = sleepRemainingMs(timer, now)
  return ms === null ? null : Math.ceil(ms / 1000)
}

/** 1:05:00 / 14:59 / 0:00 — for badges and tooltips */
export function formatSleepRemaining(seconds: number): string {
  const total = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
  return `${m}:${String(s).padStart(2, '0')}`
}

/** short label for the menu / tooltip, e.g. "15 分钟后" */
export function sleepModeLabel(timer: SleepTimer | null | undefined): string {
  if (!timer) return '未启用'
  if (timer.mode === 'minute') return `${timer.minutes ?? 0} 分钟后暂停`
  if (timer.mode === 'track') return '播完当前歌曲后暂停'
  return '播完当前队列后暂停'
}

/**
 * Timer state after one elapsed tick: still armed, or null when the
 * countdown has run out (the caller then pauses playback).
 */
export function sleepTickOnTime(
  timer: SleepTimer | null | undefined,
  now: number
): SleepTimer | null {
  if (!timer || timer.mode !== 'minute' || timer.deadline === null) return timer ?? null
  return now >= timer.deadline ? null : timer
}

export interface EndedContext {
  sleep: SleepTimer | null
  /** play mode in effect ('one' repeats the same track forever) */
  playMode: string
  /** index of the track that just ended */
  endedIndex: number
  /** queue length at the moment the track ended */
  queueLength: number
  /** true → the user pressed next (explicit intent wins over ended-driven modes) */
  manual: boolean
}

/**
 * What the player should do when a track ends while a sleep timer is armed.
 *
 * Returns 'stop' (pause, do not advance) or 'advance' (normal behaviour:
 * repeat the single track in 'one' mode, otherwise load the next one).
 */
function decideEnded(ctx: EndedContext): 'stop' | 'advance' {
  if (!ctx.sleep) return 'advance'
  if (ctx.manual) return 'advance' // user chose to move on — let them
  // an ended-driven timer always suppresses the repeat of 'one' mode
  if (ctx.sleep.mode === 'track') return 'stop'
  if (ctx.sleep.mode === 'queue') {
    // F7: in 'one' mode the same track repeats forever, so endedIndex can never
    // reach the last position — treat the mode as a one-track queue so
    // "播完当前队列" still fires (exactly the "going to sleep" use case).
    if (ctx.playMode !== 'one') return 'stop'
    const singleTrack = ctx.queueLength <= 1
    if (singleTrack || ctx.endedIndex >= ctx.queueLength - 1) return 'stop'
    return 'advance'
  }
  return 'advance' // countdown mode: keep playing until the clock says stop
}

export function shouldStopOnEnded(ctx: EndedContext): boolean {
  return decideEnded(ctx) === 'stop'
}
